    segment: &str,
    budget: &EvalBudget,
) -> Result<(), ExpressionError> {
    if segment.len() > MAX_FORMAT_OUTPUT_BYTES - output.len() {
        return Err(ExpressionError::FormatOutputTooLarge(
            MAX_FORMAT_OUTPUT_BYTES,
        ));
    }
    if segment.len() > budget.remaining().saturating_sub(output.len()) {
