pub(super) fn eval(
    expr: &Expr,
    context: &Context,
    budget: &mut EvalBudget,
) -> Result<Value, ExpressionError> {
    let value = match expr {
        Expr::Literal(value) => {
            budget.charge(value)?;
            return Ok(value.clone());
        }
        Expr::Path(path) => {
            if let Some(value) = context.resolve_ref(path) {
                budget.charge(value)?;
                return Ok(value.clone());
