        Expr::Binary { .. } => eval_binary(expr, context, budget),
        Expr::Call { name, args } => eval_call(name, args, context, budget),
        Expr::MemberAccess { expr, path } => eval_member(expr, path, context, budget),
    }?;
    budget.charge(&value)?;
    Ok(value)
}

